{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-independent controls preventing public ACLs or bucket policies. An accidental future policy or ACL change could expose log data publicly."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The log bucket has no lifecycle controls, leaving incomplete multipart uploads indefinitely retained. A lifecycle rule can clean these abandoned uploads without deleting completed logs."
    },
    {
      "check_id": "CKV2_AWS_62",
      "title": "S3 bucket event notifications are not enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "Bucket activity is not published through S3 event notifications, limiting integration with monitoring and detection workflows. Enabling EventBridge provides an event stream without requiring a new notification destination resource."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Log bucket permits destructive deletion",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "With force_destroy enabled, Terraform can delete the bucket and all versioned log objects without requiring them to be removed separately. This weakens protection against accidental or unauthorized loss of audit data."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_notification" "logs" {
  bucket      = aws_s3_bucket.logs.id
  eventbridge = true
}
",
  "fix_summary": "Added comprehensive S3 public-access blocking, a lifecycle rule for abandoned multipart uploads, and EventBridge event notifications. Disabled force-destroy to protect versioned log data from automatic destructive deletion."
}
